import sys

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    pts = []
    for i in range(n):
        x, y = data[1 + 2 * i: 3 + 2 * i]
        pts.append((x, y))

    # A sequence of choices removes precisely the points comparable to a
    # chosen point in the same (increasing) direction. The chosen points
    # must therefore form an antichain. For a fixed antichain, the remaining
    # points are those crossing every chosen point in the permutation diagram.
    # Count distinct such common-neighbour sets by generating all antichains
    # and deduplicating their resulting bitmasks.
    pts.sort()
    ys = [y for x, y in pts]
    allmask = (1 << n) - 1
    adj = [0] * n
    for i in range(n):
        for j in range(n):
            if (i - j) * (ys[i] - ys[j]) < 0:
                adj[i] |= 1 << j

    outputs = {allmask}
    # Permutation antichains are decreasing subsequences. Enumerate recursively;
    # the mask accumulated is the intersection of their neighbourhoods.
    # Identical resulting sets are stored only once.
    stack = [(0, -1, allmask)]
    while stack:
        start, last, common = stack.pop()
        for i in range(start, n):
            if last < 0 or ys[last] > ys[i]:
                nxt = common & adj[i]
                outputs.add(nxt)
                stack.append((i + 1, i, nxt))

    print(len(outputs) % MOD)

if __name__ == '__main__':
    main()

