import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    N = data[0]
    A = data[1:]

    factors = []
    primes = set()
    for x in A:
        d = {}
        q = x
        p = 2
        while p * p <= q:
            if q % p == 0:
                e = 0
                while q % p == 0:
                    q //= p
                    e += 1
                d[p] = e
                primes.add(p)
            p += 1
        if q > 1:
            d[q] = d.get(q, 0) + 1
            primes.add(q)
        factors.append(d)

    answer = 1
    for prime in primes:
        steps = [d.get(prime, 0) for d in factors]
        max_height = sum(steps)
        power = [1] * (max_height + 1)
        for h in range(1, max_height + 1):
            power[h] = power[h - 1] * prime % MOD
        # prime_to_t[t] = prime**t, used when the running minimum decreases.
        prime_to_t = [1] * (N + 1)
        for t in range(1, N + 1):
            prime_to_t[t] = prime_to_t[t - 1] * prime % MOD

        # dp[h] sums scores of partial sign choices, normalized so their
        # minimum valuation so far is zero; h is the current valuation.
        dp = {0: 1}
        for t, e in enumerate(steps, 1):
            nd = {}
            if e == 0:
                for h, value in dp.items():
                    nd[h] = (nd.get(h, 0) + value * power[h]) % MOD
            else:
                for h, value in dp.items():
                    nh = h + e
                    nd[nh] = (nd.get(nh, 0) + value * power[nh]) % MOD
                    if h >= e:
                        nh = h - e
                        nd[nh] = (nd.get(nh, 0) + value * power[nh]) % MOD
                    else:
                        # The new position is below every previous one. Shift
                        # all t existing valuations up by e-h to normalize.
                        delta = e - h
                        shift = pow(prime_to_t[t], delta, MOD)
                        nd[0] = (nd.get(0, 0) + value * shift) % MOD
            dp = nd

        answer = answer * (sum(dp.values()) % MOD) % MOD

    print(answer)

if __name__ == '__main__':
    main()

