class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        groups = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            groups[b].append((a, i))

        heap = []  # (-left endpoint, pair index)
        gains = [0] * len(conflictingPairs)
        total = 0

        for right in range(1, n + 1):
            for left, idx in groups[right]:
                heapq.heappush(heap, (-left, idx))

            if not heap:
                total += right
                continue

            neg_left, idx = heapq.heappop(heap)
            largest = -neg_left
            second_largest = -heap[0][0] if heap else 0
            heapq.heappush(heap, (neg_left, idx))

            total += right - largest
            if second_largest < largest:
                gains[idx] += largest - second_largest

