import sys
input = sys.stdin.buffer.readline

N, M, Q = map(int, input().split())
edges = []
for _ in range(M):
    a, b, c = map(int, input().split())
    edges.append((a - 1, b - 1, c))

queries = []
deleted = set()
for _ in range(Q):
    data = list(map(int, input().split()))
    queries.append(tuple(data))
    if data[0] == 1:
        deleted.add(data[1] - 1)

INF = 10**30
dist = [[INF] * N for _ in range(N)]
for i in range(N):
    dist[i][i] = 0
for i, (a, b, c) in enumerate(edges):
    if i not in deleted:
        dist[a][b] = dist[b][a] = c

# All-pairs shortest paths in the graph after every forward deletion.
for k in range(N):
    row_k = dist[k]
    for i in range(N):
        row_i = dist[i]
        dik = row_i[k]
        if dik == INF:
            continue
        for j in range(N):
            candidate = dik + row_k[j]
            if candidate < row_i[j]:
                row_i[j] = candidate

answers = []
for query in reversed(queries):
    if query[0] == 2:
        _, x, y = query
        value = dist[x - 1][y - 1]
        answers.append(str(value if value < INF else -1))
    else:
        _, road_id = query
        a, b, c = edges[road_id - 1]

        # Adding one undirected edge can improve a shortest path only by
        # using that edge once; the distances on either side are already known.
        col_a = [dist[i][a] for i in range(N)]
        col_b = [dist[i][b] for i in range(N)]
        row_a = dist[a][:]
        row_b = dist[b][:]
        for i in range(N):
            row_i = dist[i]
            to_a = col_a[i] + c
            to_b = col_b[i] + c
            for j in range(N):
                candidate = to_a + row_b[j]
                if candidate < row_i[j]:
                    row_i[j] = candidate
                candidate = to_b + row_a[j]
                if candidate < row_i[j]:
                    row_i[j] = candidate

print("\n".join(reversed(answers)))

