class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        mod = 10**9 + 7
        m = min(n, x)
        dp = [0] * (m + 1)
        dp[0] = 1

        # dp[k] counts assignments to the first i performers with k
        # occupied stages, multiplied by y**k for the bands' score choices.
        for i in range(1, n + 1):
            for k in range(min(i, m), 0, -1):
                dp[k] = (k * dp[k] + (x - k + 1) * y * dp[k - 1]) % mod
            dp[0] = 0

        return sum(dp) % mod

