import sys
from collections import deque

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n, m, q = next(it), next(it), next(it)
    people = [(next(it), next(it)) for _ in range(m)]
    queries = [(next(it), next(it)) for _ in range(q)]
    out = []
    for L, R in queries:
        parent = list(range(n + 1))
        size = [1] * (n + 1)
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        for i in range(L - 1, R):
            s, t = people[i]
            a, b = find(s), find(t)
            if a != b:
                if size[a] < size[b]:
                    a, b = b, a
                parent[b] = a
                size[a] += size[b]
        edges = []
        indeg = [0] * (n + 1)
        for i in range(L - 1, R):
            s, t = people[i]
            a = find(s)
            lo, hi = (s, t) if s < t else (t, s)
            # Rightward travel requires interior potential greater than endpoints;
            # leftward travel requires it smaller.
            greater = s < t
            for x in range(lo + 1, hi):
                b = find(x)
                if a == b:
                    edges.append((-1, -1))
                    break
                if greater:
                    edges.append((a, b))
                else:
                    edges.append((b, a))
            if edges and edges[-1] == (-1, -1):
                break
        else:
            adj = [[] for _ in range(n + 1)]
            for a, b in edges:
                adj[a].append(b)
                indeg[b] += 1
            roots = {find(x) for x in range(1, n + 1)}
            dq = deque(x for x in roots if indeg[x] == 0)
            seen = 0
            while dq:
                u = dq.popleft()
                seen += 1
                for v in adj[u]:
                    indeg[v] -= 1
                    if indeg[v] == 0:
                        dq.append(v)
            out.append('Yes' if seen == len(roots) else 'No')
            continue
        out.append('No')
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

