class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        size = n * m
        # Clockwise turns in grid coordinates: SE -> SW -> NW -> NE -> SE.
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        straight = []

        # straight[d][0/1] gives maximal straight alternating length when
        # the current cell is respectively 2 / 0.
        for dr, dc in dirs:
            two = [0] * size
            zero = [0] * size
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            for r in rows:
                for c in cols:
                    i = r * m + c
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < m:
                        j = nr * m + nc
                        next_two, next_zero = two[j], zero[j]
                    else:
                        next_two = next_zero = 0
                    if grid[r][c] == 2:
                        two[i] = 1 + next_zero
                    elif grid[r][c] == 0:
                        zero[i] = 1 + next_two
            straight.append((two, zero))

        answer = 0
        for d, (dr, dc) in enumerate(dirs):
            turn_dir = (d + 1) % 4
            turn_dr, turn_dc = dirs[turn_dir]
            turn_two, turn_zero = straight[turn_dir]
            # With one turn remaining, indexed by the value required here.
            dp_two = [0] * size
            dp_zero = [0] * size
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            for r in rows:
                for c in cols:
                    i = r * m + c
                    nr, nc = r + dr, c + dc
                    if grid[r][c] == 2:
                        best = 0
                        if 0 <= nr < n and 0 <= nc < m:
                            j = nr * m + nc
                            best = max(dp_zero[j], turn_zero[j])
                        dp_two[i] = 1 + best
                    elif grid[r][c] == 0:
                        best = 0
                        if 0 <= nr < n and 0 <= nc < m:
                            j = nr * m + nc
                            best = max(dp_two[j], turn_two[j])
                        dp_zero[i] = 1 + best

            for r in range(n):
                for c in range(m):
                    if grid[r][c] == 1:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            answer = max(answer, 1 + dp_two[nr * m + nc])
                        else:
                            answer = max(answer, 1)
        return answer

