class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2

        # Powers of 10 modulo k for each decimal position.
        powers = [1] * n
        for i in range(1, n):
            powers[i] = (powers[i - 1] * 10) % k

        # A half-string digit contributes to its mirrored pair, or just
        # the center position when n is odd.
        coeff = []
        for j in range(m):
            if n % 2 and j == m - 1:
                coeff.append(powers[j])
            else:
                coeff.append((powers[j] + powers[n - 1 - j]) % k)

        # dp[i] is a bitmask of residues attainable by half positions i..m-1.
        full_mask = (1 << k) - 1
        dp = [0] * (m + 1)
        dp[m] = 1  # The empty suffix has residue zero.
        for i in range(m - 1, -1, -1):
            mask = 0
            c = coeff[i]
            for digit in range(10):
                shift = (c * digit) % k
                attainable = dp[i + 1]
                if shift:
                    attainable = ((attainable << shift) |
                                  (attainable >> (k - shift))) & full_mask
                mask |= attainable
            dp[i] = mask

        # Greedily maximize the left half while preserving feasibility.
        required = 0
        half = []
        for i, c in enumerate(coeff):
            lower = 1 if i == 0 else 0
            for digit in range(9, lower - 1, -1):
                remainder = (required - c * digit) % k
                if dp[i + 1] & (1 << remainder):
                    half.append(str(digit))
                    required = remainder
                    break

        left = ''.join(half)
        return left + (left[:-1][::-1] if n % 2 else left[::-1])

