class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter

        freq = Counter(s)
        counts = [freq.get(chr(97 + i), 0) for i in range(26)]
        answer = len(s)

        for target in range(1, max(counts) + 1):
            # surplus reaching this letter -> minimum cost so far
            dp = {0: 0}
            for i, original in enumerate(counts):
                ndp = {}
                for incoming, cost in dp.items():
                    for desired in (0, target):
                        balance = original + incoming - desired
                        if i == 25:
                            # No letter follows z; any remaining surplus is deleted.
                            new_incoming = 0
                            new_cost = cost + abs(balance)
                        elif balance >= 0:
                            # Change all surplus characters to the next letter.
                            new_incoming = balance
                            new_cost = cost + balance
                        else:
                            # Insert enough characters to reach the desired count.
                            new_incoming = 0
                            new_cost = cost - balance
                        old = ndp.get(new_incoming)
                        if old is None or new_cost < old:
                            ndp[new_incoming] = new_cost
                dp = ndp
            answer = min(answer, min(dp.values()))

        return answer

