from typing import List

class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        # Root the tree iteratively so even a path-shaped tree is safe.
        parent = [-1] * n
        parent[0] = 0
        order = [0]
        for u in order:
            for v, _ in graph[u]:
                if v != parent[u]:
                    parent[v] = u
                    order.append(v)

        # dp0[u]: best subtree value if the edge to the parent is absent.
        # dp1[u]: best subtree value if the edge to the parent is present.
        dp0 = [0] * n
        dp1 = [0] * n
        for u in reversed(order):
            base = 0
            gains = []
            for v, w in graph[u]:
                if parent[v] == u:
                    base += dp0[v]
                    gains.append(w + dp1[v] - dp0[v])

            gains.sort(reverse=True)
            value_without_parent = base
            value_with_parent = base
            for i, gain in enumerate(gains):
                if gain <= 0:
                    break
                if i < k:
                    value_without_parent += gain
                if i < k - 1:
                    value_with_parent += gain
            dp0[u] = value_without_parent
            dp1[u] = value_with_parent

        return dp0[0]

