def fwht(a):
 n=len(a); h=1
 while h<n:
  step=h*2
  for i in range(0,n,step):
   for j in range(i,i+h):
    x=a[j];y=a[j+h];a[j]=x+y;a[j+h]=x-y
  h=step

def sol(rows,w):
 n=1<<w;c=[0]*n
 for r in rows:c[r]+=1
 k=[min(x.bit_count(),w-x.bit_count()) for x in range(n)]
 fwht(c);fwht(k);v=[x*y for x,y in zip(c,k)];fwht(v)
 return min(x//n for x in v)
